interface Repository {
    void save(String item);
    String findById(int id);
    void delete(int id);
}

// Legal: Abstract class implements interface without implementing all methods!
abstract class BaseSqlRepository implements Repository {
    protected String tableName;
    public BaseSqlRepository(String tableName) { this.tableName = tableName; }

    // Implements delete() for all SQL tables
    @Override
    public void delete(int id) {
        System.out.println("DELETE FROM " + tableName + " WHERE id = " + id);
    }
    // save() and findById() left abstract for concrete subclasses!
}

class UserRepository extends BaseSqlRepository {
    public UserRepository() { super("users"); }

    @Override
    public void save(String user) {
        System.out.println("INSERT INTO " + tableName + " VALUES ('" + user + "')");
    }

    @Override
    public String findById(int id) {
        return "SELECT * FROM " + tableName + " WHERE id = " + id;
    }
}

public class RepoDemo {
    public static void main(String[] args) {
        Repository repo = new UserRepository();
        repo.save("Alice");
        repo.delete(42);
    }
}

