interface SmartDevice {
    void connectWifi(String ssid);
    void disconnect();
}

class SmartBulb implements SmartDevice {
    private String bulbId;
    public SmartBulb(String bulbId) { this.bulbId = bulbId; }
    @Override
    public void connectWifi(String ssid) {
        System.out.println(bulbId + " connected to SSID: " + ssid);
    }
    @Override
    public void disconnect() {
        System.out.println(bulbId + " disconnected from WiFi");
    }
}

public class SmartApp {
    public static void main(String[] args) {
        SmartDevice device = new SmartBulb("BULB-01");
        device.connectWifi("HomeNet_5G");
        device.disconnect();
    }
}

class FinancialAsset {
    protected String ticker;
    protected double marketValue;
    public FinancialAsset(String ticker, double marketValue) {
        this.ticker = ticker;
        this.marketValue = marketValue;
    }
    public void displayAsset() {
        System.out.println("Asset: " + ticker + " | Value: $" + String.format("%.2f", marketValue));
    }
}

interface Auditable {
    void conductAudit(String auditorName);
}

class StockHolding extends FinancialAsset implements Auditable {
    public StockHolding(String ticker, double marketValue) {
        super(ticker, marketValue);
    }
    @Override
    public void conductAudit(String auditorName) {
        System.out.println("[AUDIT BY " + auditorName + "] Verified ticker " + ticker + " at $" + String.format("%.2f", marketValue));
    }
}

public class AssetApp {
    public static void main(String[] args) {
        StockHolding stock = new StockHolding("AAPL", 182.50);
        stock.displayAsset();
        stock.conductAudit("KPMG");
    }
}

practiceProblems.problemStatement:
Implement an interface partially in an abstract class from scratch:

1. Interface NetworkEndpoint:
   - Method 1: void open(String host);
   - Method 2: void ping();

2. Abstract Class AbstractEndpoint (implements NetworkEndpoint):
   - Method: @Override public void ping() printing 'Pinging host: ' + host
   - Leave open(String host) abstract

3. Class OracleEndpoint (extends AbstractEndpoint):
   - Method: @Override public void open(String host) setting this.host = host and printing 'Oracle TNS listener opened at ' + host

Test in Main:
NetworkEndpoint ep = new OracleEndpoint();
ep.open("db.corp.net");
ep.ping();.

practiceProblems.solutionCode:
interface DatabaseDriver {
    void open();
    void ping();
    void close();
}

abstract class AbstractDriver implements DatabaseDriver {
    protected String host;
    public AbstractDriver(String host) {
        this.host = host;
    }
    @Override
    public void ping() {
        System.out.println("Pinging host: " + host);
    }
}

class OracleDriver extends AbstractDriver {
    public OracleDriver(String host) {
        super(host);
    }
    @Override
    public void open() {
        System.out.println("Oracle TNS listener opened at " + host);
    }
    @Override
    public void close() {
        System.out.println("Oracle session closed");
    }
}

public class DriverApp {
    public static void main(String[] args) {
        DatabaseDriver driver = new OracleDriver("db.corp.net");
        driver.open();
        driver.ping();
        driver.close();
    }
}

