practiceProblems.problemStatement:
Process messages through an interface array from scratch:

1. Interface NotificationSender:
   - Method: void send(String recipient, String message);

2. Implementing Classes:
   - Class EmailSender: @Override public void send(r, m) printing '[Email] Sent to <r>: <m>'
   - Class SmsSender: @Override public void send(r, m) printing '[SMS] Dispatched to <r>: <m>'

Test in Main:
NotificationSender[] senders = { new EmailSender(), new SmsSender() };
senders[0].send("dev@corp.com", "Deploy completed");
senders[1].send("+15551234", "Server load 98%");.

practiceProblems.solutionCode:
interface MessageSender {
    boolean send(String recipient, String message);
}

class EmailSender implements MessageSender {
    @Override
    public boolean send(String recipient, String message) {
        System.out.println("[Email] Sent to " + recipient + ": " + message);
        return true;
    }
}

class SmsSender implements MessageSender {
    @Override
    public boolean send(String recipient, String message) {
        if (recipient.startsWith("+")) {
            System.out.println("[SMS] Dispatched to " + recipient + ": " + message);
            return true;
        } else {
            System.out.println("[SMS] Error: Invalid international number " + recipient);
            return false;
        }
    }
}

class NotificationQueue {
    public void processAll(MessageSender[] senders, String[] recipients, String msg) {
        for (int i = 0; i < senders.length; i++) {
            senders[i].send(recipients[i], msg);
        }
    }
}

public class QueueApp {
    public static void main(String[] args) {
        MessageSender[] senders = new MessageSender[] { new EmailSender(), new SmsSender() };
        String[] recipients = new String[] { "dev@corp.com", "+15550199" };
        NotificationQueue queue = new NotificationQueue();
        queue.processAll(senders, recipients, "Deploy completed");
    }
}
